 70	  start() {
 71	    if (this.refreshTimer || !this.collectLiveRows) {
 72	      return;
 73	    }
 74	    this.refreshTimer = setInterval(() => {
 75	      this.refreshNow().catch((error) => {
 76	        this.logger.warn("live_status.refresh_failed", { error });
 77	      });
 78	    }, this.refreshIntervalMs);
 79	    this.refreshTimer.unref?.();
 80	  }
